<script setup lang="ts">
import type { StudentNotificationCategory,StudentNotificationFilters,StudentNotificationSeverity } from "~/composables/useStudentNotifications";
definePageMeta({layout:"student",middleware:["student"],title:"Notifications",roleTitle:"Student"}); const center=useStudentNotifications(), auth=useAuth(), toast=useToast(); const filters=reactive<StudentNotificationFilters>({view:"active",search:"",category:"all",severity:"all",page:1,pageSize:10}); const searchInput=ref(""), acting=ref<string|null>(null), markingAll=ref(false); const views=[{label:"Active",value:"active",icon:"i-lucide-bell-ring"},{label:"Unread",value:"unread",icon:"i-lucide-mail"},{label:"Needs Attention",value:"attention",icon:"i-lucide-triangle-alert"},{label:"Read",value:"read",icon:"i-lucide-mail-check"},{label:"All",value:"all",icon:"i-lucide-list-filter"}] as const; const categories=["all","Circulation","Reservation","Membership","Library Card","Announcement","Security","System"] as const; const severities=["all","Critical","Warning","Info","Success"] as const; const metrics=computed(()=>[{label:"Unread",value:center.summary.value.unread,icon:"i-lucide-mail",description:"New notices not yet reviewed"},{label:"Needs Attention",value:center.summary.value.attention,icon:"i-lucide-triangle-alert",description:"Items that may require action"},{label:"Critical",value:center.summary.value.critical,icon:"i-lucide-octagon-alert",description:"Urgent Library concerns"},{label:"Announcements",value:center.summary.value.announcements,icon:"i-lucide-megaphone",description:"Current Library announcements"}]);
async function load(){try{await Promise.all([center.load(filters),center.loadSummary()]);}catch(e){toast.add({title:"Notifications could not be loaded",description:auth.getErrorMessage(e),color:"error",icon:"i-lucide-circle-alert"});}}
async function refresh(){try{await center.sync(); filters.page=1; await center.load(filters); toast.add({title:"Notifications refreshed",color:"success",icon:"i-lucide-refresh-cw"});}catch(e){toast.add({title:"Refresh failed",description:auth.getErrorMessage(e),color:"error"});}}
async function setRead(id:string,value:boolean){acting.value=id;try{await center.setRead(id,value); if((filters.view==="unread"&&value)||(filters.view==="read"&&!value))await center.load(filters);}finally{acting.value=null;}}
async function allRead(){markingAll.value=true;try{await center.markAllRead();await center.load(filters);}finally{markingAll.value=false;}}
function applySearch(){filters.search=searchInput.value.trim();filters.page=1;void load();} function reset(){searchInput.value="";Object.assign(filters,{view:"active",search:"",category:"all",severity:"all",page:1});void load();}
watch(()=>[filters.view,filters.category,filters.severity],()=>{filters.page=1;void load();}); watch(()=>filters.page,()=>void load()); onMounted(load);
</script>
<template><div class="space-y-6 p-4 sm:p-6 lg:p-8"><StudentPageHeader eyebrow="Messages and Reminders" title="Notifications" description="Review due-date reminders, reservation updates, membership notices, and official Library announcements." icon="i-lucide-bell"><template #actions><UButton label="Mark All Read" icon="i-lucide-mail-check" color="neutral" variant="outline" :disabled="center.summary.value.unread===0" :loading="markingAll" @click="allRead"/><UButton label="Refresh" icon="i-lucide-refresh-cw" color="primary" :loading="center.loading.value" @click="refresh"/></template></StudentPageHeader><UAlert v-if="center.error.value" color="error" variant="soft" icon="i-lucide-circle-alert" title="Notifications unavailable" :description="center.error.value"/><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StudentMetricCard v-for="item in metrics" :key="item.label" v-bind="item"/></div><UCard><div class="space-y-4"><div class="flex flex-wrap gap-2"><UButton v-for="item in views" :key="item.value" :label="item.label" :icon="item.icon" :color="filters.view===item.value?'primary':'neutral'" :variant="filters.view===item.value?'solid':'outline'" size="sm" @click="filters.view=item.value"/></div><div class="grid gap-3 lg:grid-cols-[1fr_13rem_11rem_auto]"><UInput v-model="searchInput" icon="i-lucide-search" placeholder="Search notification title or message" @keyup.enter="applySearch"/><USelect v-model="filters.category" :items="categories.map(v=>({label:v==='all'?'All categories':v,value:v}))"/><USelect v-model="filters.severity" :items="severities.map(v=>({label:v==='all'?'All severity levels':v,value:v}))"/><div class="flex gap-2"><UButton label="Search" icon="i-lucide-search" @click="applySearch"/><UButton icon="i-lucide-rotate-ccw" color="neutral" variant="outline" aria-label="Reset filters" @click="reset"/></div></div></div></UCard><div v-if="center.loading.value&&!center.notifications.value.length" class="space-y-3"><USkeleton v-for="n in 4" :key="n" class="h-40 rounded-2xl"/></div><UCard v-else-if="!center.notifications.value.length"><div class="py-12 text-center"><div class="mx-auto flex size-14 items-center justify-center rounded-2xl bg-muted text-muted"><UIcon name="i-lucide-bell-off" class="size-7"/></div><h2 class="mt-4 text-lg font-semibold text-highlighted">No notifications found</h2><p class="mt-2 text-sm text-muted">There are no records matching the selected filters.</p></div></UCard><div v-else class="space-y-3"><StudentNotificationCard v-for="item in center.notifications.value" :key="item.documentId" :notification="item" :busy="acting===item.documentId" @read="value=>setRead(item.documentId,value)"/></div><div v-if="center.pagination.value.pageCount>1" class="flex justify-center"><UPagination v-model:page="filters.page" :total="center.pagination.value.total" :items-per-page="center.pagination.value.pageSize"/></div></div></template>
